# Read-only duration profiles: uniform measurements and actual music-warp points.
from pathlib import Path
import json
from dunhuang.research.execution_planning_r58.common import ROOT,fresh,read,write,sha
def main():
 out=fresh(ROOT/'profiles/viewer');uniform=read(ROOT/'main/uniform_profiles.json');plans=read(ROOT/'controls/result.json');units={u['unit_uid']:u for u in read('outputs/event_coverage_r47_01/index/result.json')['units']};rows=[];points=[]
 for uid in sorted({r['event_uid'] for r in uniform},key=lambda uid:(units[uid]['source_uid'],units[uid]['source_interval'])):
  group=[r for r in uniform if r['event_uid']==uid];u=units[uid];values=[]
  for r in group:
   v=dict(duration=r['duration'],legal=r['legal'])
   if r['legal']:v.update({f'D{k}':r['metrics'][f'D{k}_Q95'] for k in (1,2,3)});v.update({f'A{k}':r['source_normalized'][str(k)]['ratio'] for k in (1,2,3)});v['cost']=r['execution_cost']
   values.append(v)
  rows.append(dict(event_uid=uid,source_uid=u['source_uid'],source_interval=u['source_interval'],values=values))
 # Fixed baselines have no embedded R58 profile; recompute by the frozen sampler.
 from dunhuang.research.execution_planning_r58.profiles import Assets
 assets=Assets()
 for r in plans['records']:
  for slot,e in enumerate(r['events']):
   u=units[e['event_uid']];result=assets.node(u,e['target_interval'],assets.pop.tracks[r['song']]);assert result is not None;n,_=result;assert n['warp']==e['time_warp'];points.append(dict(song=r['song'],arm=r['arm'],slot=slot,event_uid=e['event_uid'],duration=e['target_interval'][1]-e['target_interval'][0],**{f'D{k}':n['metrics'][f'D{k}_Q95'] for k in (1,2,3)},**{f'A{k}':n['source_normalized'][str(k)]['ratio'] for k in (1,2,3)},cost=n['execution_cost'],target=e['target_interval']))
 (out/'data.js').write_bytes(('window.PROFILES='+json.dumps(dict(events=rows,actual=points),ensure_ascii=False,allow_nan=False)+';').encode())
 html='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>R58 来源执行档案</title><style>body{max-width:1200px;margin:28px auto;padding:18px;font:18px system-ui;background:#f4f1e8;color:#173e36}select{padding:10px}canvas{width:100%;background:white}table{border-collapse:collapse;width:100%}td,th{padding:8px;border-bottom:1px solid #ccc}#hint{background:#dfe9dc;padding:14px}</style><h1>R58 · 来源条件执行档案</h1><p>灰线：同一来源的匀速重定时实测；彩色点：各方案实际音乐拍点下的 E1-W 测量。两种时间映射不同，不能把彩色点当作灰线预测。</p><select id="event"></select> <select id="song"><option value="0">敦煌音乐2</option><option value="1">敦煌音乐3</option><option value="2">敦煌音乐4</option></select> <select id="metric"><option>D1</option><option>D2</option><option selected>D3</option><option>A1</option><option>A2</option><option>A3</option><option>cost</option></select><p id="hint"></p><canvas id="chart" width="1160" height="470"></canvas><p>横轴为目标Core帧数（30FPS）；D1/D2/D3为相对身体FK差分Q95，单位m/s、m/s²、m/s³；A1/A2/A3为来源归一化比值，cost为对称执行变形代价。较低D3不自动代表自然。近静态分母保持UNKNOWN。</p><table><thead><tr><th>方案</th><th>槽位</th><th>目标帧区间</th><th>Core长度</th><th>当前指标实测</th></tr></thead><tbody id="rows"></tbody></table><p>所有格点与来源区间可追溯；边界状态为局部观测有限差分。世界Root／接触、文化语义及Native24仍未知或不可评。</p><script src="data.js"></script><script>
 const $=x=>document.getElementById(x),colors={B0:'#9d6924',B1:'#218873',C1:'#9b52a9',C2:'#3164c5',C3:'#cb712c'};PROFILES.events.forEach((e,i)=>$('event').add(new Option(e.source_uid+' ['+e.source_interval.join(',')+')',i)));function draw(){const e=PROFILES.events[+$('event').value],key=$('metric').value,actual=PROFILES.actual.filter(p=>p.song===+$('song').value&&p.event_uid===e.event_uid),valid=e.values.filter(p=>p.legal&&p[key]!=null),values=valid.map(p=>p[key]).concat(actual.filter(p=>p[key]!=null).map(p=>p[key])),max=Math.max(1e-6,...values)*1.1,c=$('chart'),g=c.getContext('2d'),x=d=>65+(d-180)/120*1060,y=v=>425-v/max*380;g.clearRect(0,0,1160,470);g.strokeStyle='#777';g.strokeRect(65,45,1060,380);g.fillStyle='#173e36';g.font='15px system-ui';for(let d=180;d<=300;d+=20){g.fillText(String(d),x(d)-12,450)}for(let k=0;k<=4;k++){let v=max*k/4;g.fillText(v.toPrecision(3),4,y(v)+5)}g.strokeStyle='#999';g.lineWidth=2;g.beginPath();let active=false;for(const p of e.values){if(!p.legal||p[key]==null){active=false;continue}active?g.lineTo(x(p.duration),y(p[key])):g.moveTo(x(p.duration),y(p[key]));active=true}g.stroke();actual.forEach((p,i)=>{if(p[key]==null)return;g.strokeStyle=colors[p.arm];g.lineWidth=3;g.beginPath();g.arc(x(p.duration),y(p[key]),4+i%4,0,Math.PI*2);g.stroke();g.fillStyle=colors[p.arm];g.fillText(p.arm+' #'+p.slot,x(p.duration)+7,y(p[key])-7)});$('hint').textContent=e.event_uid+' · 来源 ['+e.source_interval.join(',')+') · 登记180–300帧中合法 '+e.values.filter(v=>v.legal).length+'/121；非法区间不补齐。';$('rows').replaceChildren();for(const p of actual){const tr=document.createElement('tr');for(const v of [p.arm,p.slot,'['+p.target.join(',')+')',p.duration,p[key]==null?'UNKNOWN':p[key].toFixed(6)]){const td=document.createElement('td');td.textContent=v;tr.append(td)}$('rows').append(tr)}}$('event').onchange=$('song').onchange=$('metric').onchange=draw;draw();</script></html>'''
 (out/'index.html').write_bytes(html.encode());write(out/'protocol.json',dict(kind='READ_ONLY_EXECUTION_PROFILE_MEASUREMENTS_NOT_QUALITY_LABELS',uniform_sha256=sha(ROOT/'main/uniform_profiles.json'),plans_sha256=sha(ROOT/'controls/result.json'),files=[dict(name=p.name,sha256=sha(p),bytes=p.stat().st_size) for p in sorted(out.iterdir()) if p.name!='protocol.json']))
if __name__=='__main__':main()
